221	static ssize_t sf32lb_nand_read(FAR struct mtd_dev_s *dev, off_t offset,
222	                                size_t nbytes, FAR uint8_t *buffer)
223	{
224	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
225	  FAR FLASH_HandleTypeDef *handle = priv->handle;
226	  uint32_t page_size = priv->page_size;
227	  size_t remaining = nbytes;
228	  uint32_t page_addr;
229	  uint32_t page_off;
230	  uint32_t chunk;
231	  int ret;
232	
233	  if (offset < 0 || buffer == NULL || nbytes == 0)
234	    {
235	      return -EINVAL;
236	    }
237	
238	  syslog(LOG_INFO,
239	         "NAND READ entry: offset=0x%08lx nbytes=%lu buf=%p\n",
240	         (unsigned long)offset, (unsigned long)nbytes, buffer);
241	
242	  sf32lb_nand_lock();
243	
244	  while (remaining > 0)
245	    {
246	      page_addr = (uint32_t)offset / page_size * page_size;
247	      page_off = (uint32_t)offset % page_size;
248	      chunk = page_size - page_off;
249	      if (chunk > remaining)
250	        {
251	          chunk = remaining;
252	        }
253	
254	      syslog(LOG_INFO,
255	             "NAND read: off=0x%08lx page=0x%08lx chunk=%lu "
256	             "buf=%p ctable=%p isNand=%d\n",
257	             (unsigned long)offset, (unsigned long)page_addr,
258	             (unsigned long)chunk, buffer,
259	             (void *)handle->ctable, (int)handle->isNand);
260	
261	      if (handle->ctable == NULL)
262	        {
263	          syslog(LOG_ERR, "ERROR: NAND ctable is NULL!\n");
264	          sf32lb_nand_unlock();
265	          return -EIO;
266	        }
267	
268	      ret = HAL_NAND_READ_PAGE(handle, page_addr, buffer, chunk);
269	      if (ret <= 0)
270	        {
271	          syslog(LOG_ERR,
272	                 "ERROR: NAND read failed: addr=0x%08lx ret=%d\n",
273	                 (unsigned long)page_addr, ret);
274	          sf32lb_nand_unlock();
275	          return -EIO;
276	        }
277	
278	      /* Invalidate D-cache so CPU sees DMA'd data */
279	
280	      SCB_InvalidateDCache_by_Addr(buffer, chunk);
281	
282	      offset += chunk;
283	      buffer += chunk;
284	      remaining -= chunk;
285	    }
286	
287	  sf32lb_nand_unlock();
288	  return (ssize_t)nbytes;
289	}
