133	  static struct arm_vector_table vt;
134	  struct file file;
135	  ssize_t bytes;
136	  uint32_t image_size;
137	  uint32_t remaining;
138	  uint32_t chunk;
139	  uint32_t dest;
140	  off_t src_off;
141	  int ret;
142	  uint8_t buf[SF32LB58_COPY_BUF_SIZE];
