/****************************************************************************
 * Name: test_psram
 *
 * Description:
 *   Quick read/write test of PSRAM at the application load address.
 *   Returns OK on success, -EIO on failure.
 ****************************************************************************/

static int test_psram(void)
{
  volatile uint32_t *psram = (volatile uint32_t *)SF32LB58_APP_PSRAM_LOAD_ADDR;
  const uint32_t pattern = 0xdeadbeef;
  uint32_t saved;
  int i;

  /* Save original content */

  saved = psram[0];

  /* Write pattern to first few words */

  for (i = 0; i < 4; i++)
    {
      psram[i] = pattern + i;
    }

  /* Read back and verify */

  for (i = 0; i < 4; i++)
    {
      if (psram[i] != pattern + i)
        {
          syslog(LOG_ERR,
                 "PSRAM test FAILED: [%d] wrote 0x%08lx read 0x%08lx\n",
                 i, (unsigned long)(pattern + i), (unsigned long)psram[i]);

          /* Restore original */

          psram[0] = saved;
          return -EIO;
        }
    }

  /* Restore original content */

  psram[0] = saved;

  syslog(LOG_INFO, "PSRAM test PASSED at 0x%08lx\n",
         (unsigned long)SF32LB58_APP_PSRAM_LOAD_ADDR);
  return OK;
}

