  uint32_t rlar;
  uint32_t orig_rnr = MPU->RNR;
  int psram_region = -1;

  /* Scan MPU regions to find the one covering 0x60000000 */

  for (rnr = 0; rnr < ((MPU->TYPE & MPU_TYPE_DREGION_Msk) >>
                        MPU_TYPE_DREGION_Pos); rnr++)
