       * Use ATTR_RAM_IDX which is NON_CACHEABLE in the SiFli HAL.
       * We need to set the attribute index to match the non-cacheable
       * attribute configured in MAIR.
       */

      uint32_t orig_rlar = MPU->RLAR;

      /* Configure Non-Cacheable: ATTR index 1 (ATTR_RAM_IDX = NON_CACHEABLE) */

      MPU->RLAR = (orig_rlar & ~MPU_RLAR_AttrIndx_Msk) |
                  (1U << MPU_RLAR_AttrIndx_Pos);

