/* Reconfigure PSRAM MPU region (region 5 in SiFli HAL) to
 * Non-Cacheable before the copy. The SiFli PSRAM controller's
 * write buffer may silently drop D-cache writeback writes.
 * ATTR index 1 = Non-Cacheable in SiFli MAIR.
 *
 * RBAR: base=0x60000000, SH=NON, RO=0, NP=1, XN=0 => 0x60000002
 * RLAR: limit=0x63FFFFFF, AttrIndx=1, EN=1 => 0x63FFFFE3
 * Original RLAR: AttrIndx=4 (PSRAM_WT) => 0x63FFFFE9
 */

{
  /* Read-modify-write the RLAR for region 5 to change AttrIndx to 1 */

  uint32_t rlar_orig = 0x63FFFFE9U;  /* PSRAM_WT (AttrIdx=4) */
  uint32_t rlar_nc   = 0x63FFFFE3U;  /* Non-Cacheable (AttrIdx=1) */

  /* Use inline asm to directly access MPU registers */

  __asm__ __volatile__(
      "mov r0, #5\n"          /* RNR = 5 (PSRAM region) */
      "mcr p15, 0, r0, c6, c2, 0\n"  /* Write RNR */
      "ldr r0, =0x63FFFFE3\n"         /* RLAR = Non-Cacheable */
      "mcr p15, 0, r0, c6, c1, 1\n"  /* Write RLAR */
      "dsb sy\n"
      "isb sy\n"
      ::: "r0"
  );

  syslog(LOG_INFO,
         "board_boot_image: PSRAM MPU region 5 set to Non-Cacheable\n");
}

